const c = 180 + randI(200);
const G = 1;
const dt = 0.25;
let particlesAmt = 1024 * 2
let massMult = rand([70, 80,100, 150, 200, 250, 300, 400, 400, 500])
let fr = (Math.PI * rand(randI(100) > 10 ? [2, 3, 3, 4, 4, 6] : [1.25, 1.5])) / particlesAmt
let width = 15
let positions, vels, thetas, running, scales, holeMass;
let holeAmt = 4 + randI(50)
let hidden = new Array(particlesAmt).fill().map((_, i) => false);
let setDefault = () => {
  positions = new Array(particlesAmt).fill().map((_, i) => new THREE.Vector2(Math.sin((i * fr)) * width, Math.cos((i * fr)) * width));
  vels = new Array(particlesAmt).fill().map((_, i) => new THREE.Vector2(0, 0));
  thetas = new Array(particlesAmt).fill().map((_, i) => Math.PI * 10);
  running = new Array(particlesAmt).fill().map((_, i) => true);
  hidden = new Array(particlesAmt).fill().map((_, i) => false);
  scales = new Array(particlesAmt).fill().map((_, i) => 1);
  holeMass = new Array(holeAmt).fill().map((_, i) => 2000 * (1 + ((1 + randI(massMult)) * 0.1)))
}
let holeSize = new Array(holeAmt).fill().map((_, i) => ((1 + randI(20)) * 0.02))
let colChance = rand([250 + randI(50)])
setDefault()
let currCol = rand(cols)
let colors = []
new Array(particlesAmt).fill().map((_, i) => {
  if (randI(300) > colChance) {
    currCol = rand(cols)
  }
  colors.push(currCol)
});
let hfr = (Math.PI * rand([2, 2, 2, 1.5, 1])) / holeAmt
let hOffset = rand([(randI(10) * 0.5) * rand([1, -1]), 0])
let hWidth = width * ((4 + randI(16)) * 0.05)
let holePos = new Array(holeAmt).fill().map((_, i) => new THREE.Vector2(hOffset + Math.sin((i * hfr)) * hWidth, Math.cos(i * hfr) * hWidth))

