let dampCount = 0
function Things() {
  useFrame(() => {
    positions.forEach((_, i) => {
      if (running[i]) {
        updateParticle(i)
        pullParticle(i)
      }
    })
    count++;
    if (!(count % 30) && started) {
      dampCount++
      if (dampCount < 25) {
        damp = 0.99
      } else {
        running = new Array(particlesAmt).fill().map((_, i) => false);
      }

    }
  })
  return (
    <Instances limit={10000} geometry={geo} material={new THREE.MeshStandardMaterial()}>
      {
        new Array(particlesAmt).fill().map((_, i) =>
          <Thing i={i} key={i} />
        )
      }
    </Instances>
  )
}
let count = 0
let m = rand([0])
let modesMult = [
  rand([0.1, 0.2, 0.5, 1, 2]) * (1 + randI(10)),
  rand([0.1, 0.2, 0.5, 1, 2]) * 20,
]
function Thing({ i }) {
  const ref = useRef();
  useFrame(() => {
    ref.current.position.x = positions[i].x
    ref.current.position.y = positions[i].y
    if (running[i]) {
      ref.current.scale.setScalar(modes[m](0, i * modesMult[0], count * modesMult[1]))
    } else {
      ref.current.scale.setScalar(0)
    }
  })
  return (
    <Instance ref={ref} position={[positions[i].x, positions[i].y, 0]} color={colors[i]} />
  )
}

let geo = new THREE.OctahedronBufferGeometry(0.04);
