function useWindowSize() {
  const [windowSize, setWindowSize] = useState({
    width: undefined,
    height: undefined,
  });
  useEffect(() => {
    function handleResize() {
      setWindowSize({
        width: window.innerWidth,
        height: window.innerHeight,
      });
    }
    window.addEventListener("resize", handleResize);
    handleResize();
    return () => window.removeEventListener("resize", handleResize);
  }, []);
  return windowSize;
}

function updateParticle(i) {
  let deltaV = vels[i].clone();
  deltaV.multiplyScalar(dt);
  positions[i].add(deltaV);
}
function pullParticle(i) {
  holePos.forEach((_, j) => {
    const force = holePos[j].clone().sub(positions[i])
    const theta = force.angle();
    const r = force.length();
    if (r <= holeSize[j]) {
      running[i] = false
    }
    const fg = G * holeMass[j] / (r * r);
    let deltaTheta = -fg * (dt / c) * Math.sin(thetas[i] - theta);
    deltaTheta /= Math.abs(1.0 - 2.0 * G * holeMass[j] / (r * c * c));
    thetas[i] += deltaTheta;
    vels[i] = new THREE.Vector2(Math.cos(thetas[i]), Math.sin(thetas[i]))
    vels[i].multiplyScalar(c * scalar);
  })
}
let scalar = rand([0.004, 0.003, 0.002, 0.002, 0.003, 0.005])

let modes = [
  (t, c, r) => Math.cos(t * 1 + Math.sqrt(c * r * 0.05)) + .5,
  (t, c, r) => Math.cos(2 * r / c ^ 2 + t),
  (t, c, r) => Math.max(0, Math.sin(r ^ (c + 9 * t))),
  (t, c, r) => Math.min(0, c / r * (Math.hypot(c + Math.cos(t) - (columns * 0.5), r - (rows * 0.5)) - 5)),
  (t, c, r) => Math.cos(c / 3 + Math.cos(r / 5 + t * 0.1) * 4) * 2,
  (t, c, r) => Math.tan(Math.sin(r / 3 - t * 2) + Math.cos(c / 2 - t * 3)),
  (t, c, r) => .02 / Math.sin(3 ** ++c - Math.atan2(c, c * r) * 3 - t),
  (t, c, r) => r / 4 & (c - 8) / r + t * 4,
  (t, c, r) => ((c * r) % (8 + Math.floor(t % 8))) > 6 ? 1 : -.5,
  (t, c, r) => (c + r < Math.max(rows, columns)) * ((c + r) < Math.ceil(Math.max(rows, columns) * 0.5) ? 1 : -1) || (c - r < 1),
  (t, c, r) => [7, 5, 3, 1].reduce((a, b) => r > a + a / 2 * Math.cos(c / a + (gt * 2) * a) ? -a / 3 : b),
  (t, c, r) => [8, 5, 3, 1].reduce((a, b) => r > a + a / 2 * Math.cos(c / a + gt * a) ? -a / 5 : b),
  (t, c, r) => ((c + (r + t * 9) ^ c - (r + t * 9)) % 13 & 1) - .15,
  (t, c, r) => Math.sin(c / 8 + t) % Math.sin(r + t),
  (t, c, r) => Math.sin(2 * Math.atan2(r - 8, c) + t),
  (t, c, r) => c < 13 ? ((Date.now() + '')[c] - 5) / 5 : 0,
  (t, c, r) => Math.sin(t) * 5 * Math.sin(r / 5) * Math.sin(c / 5) % 1,
  (t, c, r) => ((4 * 9 + c - r * Math.tan(4) ^ c * Math.tan(4) + r) & 8) - 4,
  (t, c, r) => Math.sin(t * r * c / ((r * columns) + c) * 10),
]